function rob(nums) {
  const n = nums.length;
  const best = new Array(n).fill(0);             // best[i]: the most from houses 0..i
  for (let i = 0; i < n; i++) {
    const skip = i >= 1 ? best[i - 1] : 0;       // leave house i alone
    const take = nums[i] + (i >= 2 ? best[i - 2] : 0);   // rob it: house i - 1 must be skipped
    best[i] = Math.max(skip, take);
  }
  return best[n - 1];
}

