int rob(int[] nums) {
    int twoBack = 0, oneBack = 0;                // best[i - 2], best[i - 1]
    for (int money : nums) {
        int cur = Math.max(oneBack, twoBack + money);
        twoBack = oneBack;
        oneBack = cur;
    }
    return oneBack;
}

